import type { Category } from '@/domain/models/category'
import { DEFAULT_SETTINGS, type AppSettings } from '@/domain/models/settings'
import type { TransactionRecord } from '@/domain/models/transaction'
import { parseAmountToCents } from './money'
import type { LedgerSnapshot, MoneyRepository } from '@/infrastructure/storage/repository'

export interface BackupEnvelope {
  format: 'money-app-backup'
  schemaVersion: 1
  createdAt: string
  appVersion: string
  checksum: string
  payload: LedgerSnapshot
}

function canonicalize(value: unknown): string {
  if (value === null || typeof value !== 'object') return JSON.stringify(value)
  if (Array.isArray(value)) return `[${value.map(canonicalize).join(',')}]`
  const record = value as Record<string, unknown>
  return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${canonicalize(record[key])}`).join(',')}}`
}

async function sha256Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value))
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('')
}

function portableSettings(settings: AppSettings): AppSettings {
  const { deviceId: _deviceId, licenseCode: _licenseCode, ...portable } = settings
  return { ...DEFAULT_SETTINGS, ...portable }
}

/**
 * 计算「上次备份以来新增/修改」的流水笔数；用于首页备份提醒。
 * 没有 lastBackupAt 或时间戳无效 → 视为从未备份，全部计入（鼓励首次备份）。
 */
export function countTransactionsSinceLastBackup(transactions: readonly TransactionRecord[], lastBackupAt?: string): number {
  let since = 0
  if (lastBackupAt) {
    const parsed = Date.parse(lastBackupAt)
    if (Number.isNaN(parsed)) return transactions.length
    since = parsed
  }
  let count = 0
  for (const tx of transactions) {
    if (Date.parse(tx.updatedAt) > since) count += 1
  }
  return count
}

export async function serializeBackup(snapshot: LedgerSnapshot, appVersion: string, createdAt = new Date().toISOString()): Promise<string> {
  const payload: LedgerSnapshot = structuredClone({ ...snapshot, settings: portableSettings(snapshot.settings) })
  const checksum = await sha256Hex(canonicalize(payload))
  const envelope: BackupEnvelope = { format: 'money-app-backup', schemaVersion: 1, createdAt, appVersion, checksum, payload }
  return JSON.stringify(envelope, null, 2)
}

function assertCategory(value: unknown): asserts value is Category {
  const item = value as Partial<Category>
  if (!item || typeof item !== 'object' || typeof item.id !== 'string' || typeof item.name !== 'string') throw new Error('备份中的分类格式无效')
  if (item.type !== 'income' && item.type !== 'expense') throw new Error('备份中的分类类型无效')
}

function assertTransaction(value: unknown): asserts value is TransactionRecord {
  const item = value as Partial<TransactionRecord>
  if (!item || typeof item !== 'object' || typeof item.id !== 'string' || typeof item.categoryId !== 'string') throw new Error('备份中的流水格式无效')
  if (item.type !== 'income' && item.type !== 'expense') throw new Error('备份中的流水类型无效')
  if (!Number.isSafeInteger(item.amountCents) || Number(item.amountCents) <= 0) throw new Error('备份中的金额格式无效')
  if (typeof item.bookedAt !== 'string' || Number.isNaN(Date.parse(item.bookedAt))) throw new Error('备份中的日期格式无效')
}

export async function validateBackup(text: string): Promise<LedgerSnapshot> {
  let envelope: BackupEnvelope
  try {
    envelope = JSON.parse(text) as BackupEnvelope
  } catch {
    throw new Error('备份文件不是有效的 JSON')
  }
  if (envelope.format !== 'money-app-backup' || envelope.schemaVersion !== 1 || envelope.payload?.schemaVersion !== 1) {
    throw new Error('备份格式或版本不受支持')
  }
  const expected = await sha256Hex(canonicalize(envelope.payload))
  if (expected !== envelope.checksum) throw new Error('备份校验失败，文件可能损坏或被修改')
  if (!Array.isArray(envelope.payload.categories) || !Array.isArray(envelope.payload.transactions)) throw new Error('备份缺少分类或流水')
  envelope.payload.categories.forEach(assertCategory)
  envelope.payload.transactions.forEach(assertTransaction)
  const categories = new Map(envelope.payload.categories.map((category) => [category.id, category]))
  if (envelope.payload.transactions.some((item) => {
    const category = categories.get(item.categoryId)
    return !category || category.parentId === null || category.type !== item.type
  })) throw new Error('备份包含无效分类引用')
  return structuredClone(envelope.payload)
}

export async function restoreBackup(repository: MoneyRepository, text: string): Promise<number> {
  const snapshot = await validateBackup(text)
  const currentSettings = await repository.getSettings()
  snapshot.settings = {
    ...DEFAULT_SETTINGS,
    ...snapshot.settings,
    deviceId: currentSettings.deviceId,
    licenseCode: currentSettings.licenseCode,
  }
  await repository.replaceFromSnapshot(snapshot)
  return snapshot.transactions.length
}

function csvCell(value: unknown): string {
  const text = String(value ?? '')
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text
}

export function exportCsv(snapshot: LedgerSnapshot): string {
  const categories = new Map(snapshot.categories.map((category) => [category.id, category.name]))
  const settings = portableSettings(snapshot.settings)
  const rows: unknown[][] = [
    ['record_type', 'id', 'type', 'name', 'icon', 'parent_id', 'is_default', 'disabled', 'sort_order', 'color', 'amount', 'category_id', 'category', 'note', 'date', 'created_at', 'updated_at', 'currency', 'first_day_of_week', 'last_backup_at', 'last_expense_category_id', 'last_income_category_id'],
    ['meta', 'money-app-csv-v1'],
    ['settings', 'app', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', settings.currency, settings.firstDayOfWeek, settings.lastBackupAt ?? '', settings.lastSelectedCategoryIds?.expense ?? '', settings.lastSelectedCategoryIds?.income ?? ''],
    ...snapshot.categories.map((item) => ['category', item.id, item.type, item.name, item.icon, item.parentId ?? '', item.isDefault ? 1 : 0, item.disabled ? 1 : 0, item.sortOrder, item.color ?? '', '', '', '', '', '', item.createdAt, item.updatedAt]),
    ...snapshot.transactions.map((item) => ['transaction', item.id, item.type, '', '', '', '', '', '', '', (item.amountCents / 100).toFixed(2), item.categoryId, categories.get(item.categoryId) ?? '?', item.note, item.bookedAt, item.createdAt, item.updatedAt]),
  ]
  return rows.map((row) => row.map(csvCell).join(',')).join('\r\n')
}

function parseCsvRows(text: string): string[][] {
  const rows: string[][] = []
  let row: string[] = []
  let cell = ''
  let quoted = false
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index]
    if (quoted) {
      if (char === '"' && text[index + 1] === '"') { cell += '"'; index += 1 }
      else if (char === '"') quoted = false
      else cell += char
    } else if (char === '"') quoted = true
    else if (char === ',') { row.push(cell); cell = '' }
    else if (char === '\n') { row.push(cell.replace(/\r$/, '')); rows.push(row); row = []; cell = '' }
    else cell += char
  }
  if (quoted) throw new Error('CSV 引号没有闭合')
  if (cell.length || row.length) { row.push(cell.replace(/\r$/, '')); rows.push(row) }
  return rows
}

export function parseLegacyCsv(text: string, categories: readonly Category[], now = new Date()): TransactionRecord[] {
  const rows = parseCsvRows(text)
  if (rows.length === 0) return []
  const headers = rows[0].map((value, index) => index === 0 ? value.replace(/^\uFEFF/, '') : value)
  const column = (name: string) => headers.indexOf(name)
  const required = ['type', 'amount', 'category', 'date']
  const missing = required.filter((name) => column(name) < 0)
  if (missing.length) throw new Error(`文件格式不匹配：缺少列 ${missing.join(', ')}`)
  const byId = new Map(categories.map((category) => [category.id, category]))
  const byName = new Map(categories.filter((category) => category.parentId !== null).map((category) => [category.name, category]))
  const timestamp = now.toISOString()
  return rows.slice(1).flatMap((row, index) => {
    try {
      const type = row[column('type')]
      if (type !== 'income' && type !== 'expense') return []
      const category = byId.get(row[column('category_id')]) ?? byName.get(row[column('category')])
      if (!category || category.type !== type) return []
      const bookedAt = new Date(row[column('date')]).toISOString()
      const legacyId = column('id') >= 0 ? row[column('id')] : ''
      return [{
        id: legacyId ? `legacy-${legacyId}-${index}` : crypto.randomUUID(),
        type,
        amountCents: parseAmountToCents(row[column('amount')]),
        categoryId: category.id,
        note: column('note') >= 0 ? row[column('note')] : '',
        bookedAt,
        createdAt: timestamp,
        updatedAt: timestamp,
      } satisfies TransactionRecord]
    } catch {
      return []
    }
  })
}

function fullCsvRows(text: string): { rows: string[][]; headers: string[]; column: (name: string) => number } {
  const rows = parseCsvRows(text)
  if (rows.length < 2) throw new Error('CSV 备份内容为空')
  const headers = rows[0].map((value, index) => index === 0 ? value.replace(/^\uFEFF/, '') : value)
  const column = (name: string) => headers.indexOf(name)
  if (column('record_type') < 0 || column('id') < 0) throw new Error('不是完整 CSV 备份')
  return { rows, headers, column }
}

export function isFullCsvBackup(text: string): boolean {
  try {
    const { rows, column } = fullCsvRows(text)
    return rows.slice(1).some((row) => row[column('record_type')] === 'meta' && row[column('id')] === 'money-app-csv-v1')
  } catch {
    return false
  }
}

function validIso(value: string, field: string): string {
  if (!value || Number.isNaN(Date.parse(value))) throw new Error(`CSV 备份中的${field}无效`)
  return value
}

export function validateCsvBackup(text: string): LedgerSnapshot {
  const { rows, column } = fullCsvRows(text)
  const value = (row: string[], name: string) => row[column(name)] ?? ''
  if (!rows.slice(1).some((row) => value(row, 'record_type') === 'meta' && value(row, 'id') === 'money-app-csv-v1')) throw new Error('CSV 备份格式或版本不受支持')

  const categories = rows.slice(1).filter((row) => value(row, 'record_type') === 'category').map((row) => {
    const type = value(row, 'type')
    if (type !== 'income' && type !== 'expense') throw new Error('CSV 备份中的分类类型无效')
    const sortOrder = Number.parseInt(value(row, 'sort_order'), 10)
    const colorRaw = value(row, 'color').trim()
    const category: Category = {
      id: value(row, 'id'),
      type,
      name: value(row, 'name'),
      icon: value(row, 'icon'),
      parentId: value(row, 'parent_id') || null,
      isDefault: value(row, 'is_default') === '1' || value(row, 'is_default') === 'true',
      disabled: value(row, 'disabled') === '1' || value(row, 'disabled') === 'true',
      sortOrder,
      ...(colorRaw ? { color: colorRaw } : {}),
      createdAt: validIso(value(row, 'created_at'), '分类创建时间'),
      updatedAt: validIso(value(row, 'updated_at'), '分类更新时间'),
    }
    if (!category.id || !category.name || !category.icon || !Number.isSafeInteger(category.sortOrder)) throw new Error('CSV 备份中的分类格式无效')
    return category
  })
  if (categories.length === 0) throw new Error('CSV 备份缺少分类数据')

  const transactions = rows.slice(1).filter((row) => value(row, 'record_type') === 'transaction').map((row) => {
    const type = value(row, 'type')
    if (type !== 'income' && type !== 'expense') throw new Error('CSV 备份中的流水类型无效')
    const transaction: TransactionRecord = {
      id: value(row, 'id'),
      type,
      amountCents: parseAmountToCents(value(row, 'amount')),
      categoryId: value(row, 'category_id'),
      note: value(row, 'note'),
      bookedAt: validIso(value(row, 'date'), '流水日期'),
      createdAt: validIso(value(row, 'created_at'), '流水创建时间'),
      updatedAt: validIso(value(row, 'updated_at'), '流水更新时间'),
    }
    if (!transaction.id || !transaction.categoryId) throw new Error('CSV 备份中的流水格式无效')
    return transaction
  })

  const categoryMap = new Map(categories.map((category) => [category.id, category]))
  if (categoryMap.size !== categories.length) throw new Error('CSV 备份包含重复分类编号')
  if (new Set(transactions.map((item) => item.id)).size !== transactions.length) throw new Error('CSV 备份包含重复流水编号')
  if (categories.some((category) => {
    if (!category.parentId) return false
    const parent = categoryMap.get(category.parentId)
    return !parent || parent.parentId !== null || parent.type !== category.type
  })) throw new Error('CSV 备份包含无效分类层级')
  if (transactions.some((item) => {
    const category = categoryMap.get(item.categoryId)
    return !category || category.parentId === null || category.type !== item.type
  })) throw new Error('CSV 备份包含无效分类引用')

  const settingsRow = rows.slice(1).find((row) => value(row, 'record_type') === 'settings')
  const rememberedCategory = (type: 'expense' | 'income', id: string): string | undefined => {
    const category = categoryMap.get(id)
    const parent = category?.parentId ? categoryMap.get(category.parentId) : undefined
    return category && category.type === type && category.parentId !== null && !category.disabled && parent && !parent.disabled ? category.id : undefined
  }
  const expenseId = rememberedCategory('expense', value(settingsRow ?? [], 'last_expense_category_id'))
  const incomeId = rememberedCategory('income', value(settingsRow ?? [], 'last_income_category_id'))
  const lastSelectedCategoryIds = { ...(expenseId ? { expense: expenseId } : {}), ...(incomeId ? { income: incomeId } : {}) }
  const settings: AppSettings = {
    ...DEFAULT_SETTINGS,
    currency: settingsRow?.[column('currency')] === 'CNY' ? 'CNY' : DEFAULT_SETTINGS.currency,
    firstDayOfWeek: 1,
    lastBackupAt: settingsRow ? value(settingsRow, 'last_backup_at') || undefined : undefined,
    ...(Object.keys(lastSelectedCategoryIds).length ? { lastSelectedCategoryIds } : {}),
  }
  return {
    schemaVersion: 1,
    categories: categories.sort((a, b) => Number(a.parentId !== null) - Number(b.parentId !== null) || a.sortOrder - b.sortOrder),
    transactions,
    settings,
  }
}

export async function restoreCsvBackup(repository: MoneyRepository, text: string): Promise<{ kind: 'full' | 'legacy'; count: number }> {
  if (!isFullCsvBackup(text)) {
    const records = parseLegacyCsv(text, await repository.listCategories({ includeDisabled: true }))
    for (const record of records) await repository.putTransaction(record)
    return { kind: 'legacy', count: records.length }
  }

  const snapshot = validateCsvBackup(text)
  const currentSettings = await repository.getSettings()
  snapshot.settings = {
    ...snapshot.settings,
    deviceId: currentSettings.deviceId,
    licenseCode: currentSettings.licenseCode,
  }
  await repository.replaceFromSnapshot(snapshot)
  return { kind: 'full', count: snapshot.transactions.length }
}
