import { Capacitor, registerPlugin } from '@capacitor/core'
import { Directory, Encoding, Filesystem } from '@capacitor/filesystem'
import { Share } from '@capacitor/share'

const CSV_MIME = 'text/csv;charset=utf-8'

/** 原生插件（android/.../DownloadsSaverPlugin.java）：把文件写入手机公共「下载」文件夹 */
interface DownloadsSaverPlugin {
  saveTextFile(options: { name: string; text: string; mimeType: string }): Promise<{ location: string }>
}

const DownloadsSaver = registerPlugin<DownloadsSaverPlugin>('DownloadsSaver')

function downloadWebFile(name: string, text: string, mimeType: string): void {
  const url = URL.createObjectURL(new Blob([text], { type: mimeType }))
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = name
  anchor.click()
  URL.revokeObjectURL(url)
}

/** 安卓文件名不允许冒号等字符，写入前统一清洗 */
function sanitizeFileName(name: string): string {
  return name.replace(/[\\/:*?"<>|]/g, '_')
}

/**
 * 备份到手机本地：安卓写入公共「下载」文件夹（走系统 MediaStore，无需存储权限，文件管理器可见，
 * 固定文件名只保留一份最新备份）；网页版为浏览器直接下载文件。
 */
export async function saveBackupFile(text: string, format: 'json' | 'csv'): Promise<{ name: string; location?: string }> {
  const name = `money_backup.${format}`
  if (!Capacitor.isNativePlatform()) {
    downloadWebFile(name, text, format === 'json' ? 'application/json' : CSV_MIME)
    return { name }
  }
  const result = await DownloadsSaver.saveTextFile({ name, text, mimeType: format === 'json' ? 'application/json' : 'text/csv' })
  return { name, location: result.location }
}

/**
 * 一键分享：网页版走系统分享面板（navigator.share，带文件）；浏览器不支持时退回普通下载。
 * 安卓版复用 Capacitor Share，无需选择文件。
 */
export async function shareTextFile(name: string, text: string, mimeType: string, title = '分享随手记备份'): Promise<void> {
  if (!Capacitor.isNativePlatform()) {
    if (typeof navigator !== 'undefined' && typeof navigator.share === 'function' && typeof navigator.canShare === 'function') {
      try {
        const file = new File([text], name, { type: mimeType })
        // canShare 在不支持文件分享的环境（iOS 桌面 PWA、headless 浏览器）会抛错而非返回 false，
        // 兜底成"不支持"走普通下载，不让按钮完全失效（V1.0.24 修复）
        let canShareFiles = false
        try { canShareFiles = navigator.canShare({ files: [file] }) } catch { canShareFiles = false }
        if (canShareFiles) {
          await navigator.share({ files: [file], title, text: '随手记 CSV 数据备份' })
          return
        }
      } catch (cause) {
        if (cause instanceof Error && cause.name === 'AbortError') return
        throw cause
      }
    }
    downloadWebFile(name, text, mimeType)
    return
  }
  const safeName = sanitizeFileName(name)
  await Filesystem.writeFile({ path: `shares/${safeName}`, data: text, directory: Directory.Cache, encoding: Encoding.UTF8, recursive: true })
  const cachedUri = (await Filesystem.getUri({ path: `shares/${safeName}`, directory: Directory.Cache })).uri
  await Share.share({ title, text: '随手记 CSV 数据备份', files: [cachedUri], dialogTitle: title })
}

export function pickTextFile(accept = '.json,.csv,application/json,text/csv'): Promise<{ name: string; text: string } | undefined> {
  return new Promise((resolve, reject) => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = accept
    input.onchange = async () => {
      try {
        const file = input.files?.[0]
        resolve(file ? { name: file.name, text: await file.text() } : undefined)
      } catch (error) {
        reject(error)
      }
    }
    input.click()
  })
}
